        const condition = this.parseExpression();
        let message = null;
        if (this.match(token_types_1.TokenType.COMMA)) {
            message = this.parseExpression();
        }
        this.match(token_types_1.TokenType.SEMICOLON);
        return this.builder.buildAssertStatement(condition, message, startToken, this.stream.previous());
