    // ─── Expression Precedence Hierarchy ──────────────────────────────────────
    /**
     * Entry point for expression parsing (lowest precedence to highest):
     * 1. Null-Coalescing (`??`)
     * 2. Logical OR (`OR`)
     * 3. Logical AND (`AND`)
     * 4. Logical NOT (`NOT`)
     * 5. Comparison (`==`, `=`, `!=`, `<`, `>`, `<=`, `>=`)
     * 6. Membership & Null Checks (`IN`, `NOT IN`, `BETWEEN...AND`, `CONTAINS`, `IS NULL`, `IS NOT NULL`)
     * 7. Range (`..`, `TO`)
     * 8. Additive (`+`, `-`)
     * 9. Multiplicative (`*`, `/`, `%`)
     * 10. Percentage Application (`OF`)
     * 11. Exponentiation (`^`)
     * 12. Unary (`-`, `+`, `NOT`)
     * 13. Postfix & Primary (Literals, Identifiers, Function Calls, Policy Calls, Member `.`, Index `[]`, `(...)`, Ternary `IF...THEN...ELSE`)
     */
